head.script:
///////// 1. 변수 및 선언 영역 /////////
// 세션정보를 얻기위한 함수사용
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.getPar, scwin.setPar;
scwin.vBzProcsNo;
scwin.clickBzProcsNo;
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 회사선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.vSPOT_ISU_TRD_MKT_TP_CD;
scwin.vSYMBL_INPUT_CD;
scwin.TR_JOB;
scwin.TR_ROW_POS;
scwin.gIsurCd;
scwin.gComAbbrv;
scwin.gSecugrpId;
scwin.gMktTpCd;
scwin.gAcptNo;
scwin.gAcptSeq;
scwin.gAcptNoListFee;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.elw.fn_searchCode();
        $c.cm.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_CoNmChg_Item);
        scwin.vSYMBL_INPUT_CD = js_market;
        scwin.setSymblObj();
        MxTab_1.setSelectedTabIndex(2);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성

        const parentWin = $c.lc.fn_GetRecvDocProvider();
        if (scwin.gIsurCd !== "" && scwin.gIsurCd !== undefined) {
            txb_ISUR_CD.setValue(scwin.gIsurCd);
            txb_COM_NM.setValue(scwin.gComAbbrv);
            scwin.fr_SecuGrpId = scwin.gSecugrpId;
            scwin.vSPOT_ISU_TRD_MKT_TP_CD = scwin.gMktTpCd;
            $c.lic.fn_gridNameChange(scwin.fr_SecuGrpId);
            await scwin.readRecvComnmynSync(scwin.gAcptNo);
            if (dts_RecvCoNmYn.getCellData(1, "CHECK_YN") === 'Y') {
                MxTab_1.setSelectedTabIndex(1); // 상호변경탭으로 이동

            }
            btn_Search.trigger("onclick");
        } else {
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_isunm_batch_change_onclick
 * @description 「종목명자동생성」 클릭 이벤트
