 */
scwin.btn_isunm_batch_change_onclick = async function() {
    try {
        await scwin.changeIsuNmByBatch();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.btn_isunm_batch_change_onclick" });
    }
};

/**
 * @method
 * @name cmb_COM_CHG_RSN_CD_onselchange
 * @description cmb_COM_CHG_RSN_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_COM_CHG_RSN_CD_onselchange = function() {
    /*
    저장된내용의 변경사유가 영문상호변경이면 변경후가 변경전 회사내용으로 초기화되어 나중에 수정해야됨
    	if (getObjectValue(cmb_COM_CHG_RSN_CD) == "11" || getObjectValue(cmb_COM_CHG_RSN_CD) == "12") {
    		alert("변경사유가 영문상호변경, 약명변경을 선택하면 \r\n\r\n변경후 회사정보는 변경전 회사정보로 자동설정되오니 변경항목만 수정하시면 됩니다.");

    		txb_AFCHG_COM_NM.value = dts_CoNm.NameString(1, "BFCHG_COM_NM");
    		txb_AFCHG_COM_ABBRV.value = dts_CoNm.NameString(1, "BFCHG_COM_ABBRV");
    		txb_AFCHG_COM_ENG_NM.value = dts_CoNm.NameString(1, "BFCHG_COM_ENG_NM");
    		txb_AFCHG_COM_ENG_ABBRV.value = dts_CoNm.NameString(1, "BFCHG_COM_ENG_ABBRV");
    	} else {
            //txb_AFCHG_COM_NM.value = "";
            //txb_AFCHG_COM_ABBRV.value = "";
            //txb_AFCHG_COM_ENG_NM.value = "";
            //txb_AFCHG_COM_ENG_ABBRV.value = "";
    	}
     */
};

/**
 * @method
 * @name img_COM_NM_onclick
 * @description img_COM_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_COM_NM_onclick = function() {
    try {
        scwin.getPar = scwin.getParIsur;
        scwin.setPar = scwin.setParIsur;

        // 기업인수목적 회사와 주권 목록을 나눔 2010.05.30
        if (scwin.pMenuID === "STF05201") {
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
        } else if (scwin.pMenuID === "STF05256") {
            // 기업인수목적 회사
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
        } else {
            $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
        }

        // fn_PopFindCorpChrg(fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05201.img_COM_NM_onclick" });
    }
};

/**
 * @method
 * @name img_ISUR_SYMBL_onclick
 * @description 「중복체크」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_ISUR_SYMBL_onclick = async function() {
    try {
        if (txb_AFCHG_ISUR_SYMBL.getValue() === "") {
            await $c.win.alert("[영문회사심볼]을 입력하세요.");
            txb_AFCHG_ISUR_SYMBL.focus();
            return false;
        } else {
            $c.lc.fn_chkCorpSymblDoubleInput(txb_AFCHG_ISUR_SYMBL.getValue(), txb_ISUR_CD.getValue(), dts_Symbl);
            if (!$c.ut.isEmpty(MSG_SYMBL_DOUBLE_INPUT)) {
                await $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.img_ISUR_SYMBL_onclick" });
    }
};

/**
 * @method
 * @name img_MKTACT_ENFORCE_DD_onclick
 * @description img_MKTACT_ENFORCE_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_MKTACT_ENFORCE_DD_onclick = function() {
    try {
        popUpCalendar2(edt_MKTACT_ENFORCE_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05201.img_MKTACT_ENFORCE_DD_onclick" });
