};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_ISUR_CD.getValue() === "") {
            await $c.win.alert("[회사]를 선택하세요.");
            txb_ISUR_CD.focus();
            return;
        }
        const nIndex = MxTab_1.getSelectedTabIndex();
        if (nIndex === 1) {
            await scwin.conmChgReadSync();
        } else if (nIndex === 2) {
            await scwin.issListSync();
            dts_IssList.setRowPosition(dts_IssList.getRowCount(), 0);
            dts_IssRecv.setRowPosition(dts_IssRecv.getRowCount(), 0);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {void}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = function(nIndex) {
    try {
        if (txb_ISUR_CD.getValue() !== "") {
            btn_Search.trigger("onclick");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05201.MxTab_1_OnSelChanged" });
    }
};

