 * @hidden N
 */
scwin.dts_CoNm_OnLoadCompleted = function(rowcount) {
    try {
        scwin.vBzProcsNo = dts_CoNm.getCellData(1, "BZ_PROCS_NO");
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        } else {
