/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        await scwin.conmChgReadSync();
        if (scwin.TR_JOB === "D") {
            // 삭제처리의 응답이 경우
            $c.lc.fn_alertMsg('S');
        } else {
            let chgTyp = dts_CoNm.getCellData(dts_CoNm.getRowPosition(), "COM_CHG_RSN_CD");
            if ((chgTyp === "11") || (chgTyp === "12")) {
                // 영문상호, 약명변경
                if (js_market === '2' || js_market === "6") {
                    let msg = "상호변경 및 종목명변경이 성공적으로 처리되었습니다. \r\n\r\n" + "안내문작성 버튼을 선택하여 안내문을 작성 하시기 바랍니다.";
                    await $c.win.alert(msg);
                } else {
                    // fn_alertMsg('S') ;
                    let msg = "상호변경 및 종목명변경이 성공적으로 처리되었습니다.";
                    await $c.win.alert(msg);
                }
            } else {
                let msg = "상호변경 및 종목명변경이 성공적으로 처리되었습니다. \r\n\r\n" + "주식발행내역 화면으로 이동하시어 주식발행자료를 등록(주식발행사유:상호변경) 후 상호변경 공시를 하시기 바랍니다.\r\n\r\n" + "주식발행내역 화면으로 이동하시겠습니까?" + "";
                const res = window.confirm(msg);
                if (res) {
                    MxTab_1.setSelectedTabIndex(2);
                    // btn_Iss_New.onclick();

                }
            }
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05201.trs_Save_OnSuccess" });
    }
};

