/**
 * @method
 * @name dscl
 * @description dscl 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dscl = async function() {
    let OldGet = scwin.getPar;
    let OldSet = scwin.setPar;
    if ((txb_ISUR_CD.getValue() === "") || (edt_MKTACT_ENFORCE_DD.getValue() === "")) {
        await $c.win.alert("발행기관 코드 혹은 변경상장일 자료가 없습니다.");
        return;
    }
    if (scwin.vBzProcsNo === "") {
        await $c.win.alert("먼저 저장하신후 선택하시기 바랍니다.");
        return;
    }
    if ($c.cp.isModified(dts_CoNm) || $c.cp.isModified(dts_IsuNm)) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0022", ""));
        return;
    }
    let chgTyp = dts_CoNm.getCellData(dts_CoNm.getRowPosition(), "COM_CHG_RSN_CD");
    if ((chgTyp === "11") || (chgTyp === "12")) {
        // 영문상호, 약명변경

        //  코스닥만 안내공시하다가  종목명변경 메뉴를 삭제해서 유가도 안내공시 기능추가 2009.07.17
        if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '1') {
            let OldGet = scwin.getPar;
            let OldSet = scwin.setPar;
            scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
                arr[0] = "68959"; // 68926:기타안내사항 -> 689599:종목명 변경) 으로 서식코드변경
                arr[1] = scwin.vBzProcsNo;
                arr[2] = txb_ISUR_CD.getValue();
                arr[3] = $c.lc.fn_getMktId();
                arr[4] = scwin.getIsuNmDisclsCtnt();
                arr[5] = '';

                // CopyDataSet( dts_Delistdetail , param_dts_isu) ;
                // CopyDataSet( dts_Isu , param_dts_mst) ;
                return arr.length;
            };
            scwin.setPar = function(arr) {

            };
            let wth = 730 + 5;
            let hgt = 785 + 30;
            let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
            const options = {
                id: "ULDSTF92024",
                title: "공시안내문작성",
                type: "browserPopup",
                width: wth,
                height: hgt,
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
            scwin.getPar = OldGet;
            scwin.setPar = OldSet;
        } else if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === '2' || scwin.vSPOT_ISU_TRD_MKT_TP_CD === "6") {
            const sbmOptions = {
                id : "sbm_dts_dscl",
                action : "/listingCommon.do",
                ref : "",
                target : "dts_dscl=body.content",
                isProcessMsg : false
            };

            const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
            // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            const sbmOptions2 = {
                id : "sbm_dts_dscl_Eng",
                action : "/listingCommon.do",
                ref : "",
                target : "dts_dscl_Eng=body.content",
                isProcessMsg : false
            };

            const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
            // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

            /*
            fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
            	arr[0] = "70792";
            	arr[1] = vBzProcsNo;
            	arr[2] = txb_ISUR_CD.value ;

            	CopyDataSet(dts_dscl, param_dts_mst);
            	return arr.length;
            }
             */

            /* 2009.06.12 영문공시관련추가 */
            scwin.getPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3, param_dts4, param_dts_isu_eng, param_dts_mst_eng, param_dts_dtl_eng, param_dts_rel_eng, param_dts_dtl_all_eng) {
                if (scwin.vSPOT_ISU_TRD_MKT_TP_CD === "2") {
                    arr[0] = "70792";
                } else {
                    arr[0] = "32009";
                }
                arr[1] = scwin.vBzProcsNo;
                arr[2] = txb_ISUR_CD.getValue();
                $c.stf.copyDataSet(dts_dscl, param_dts_mst);
                $c.stf.copyDataSet(dts_dscl_Eng, param_dts_mst_eng);
                return arr.length;
            };
            /* 2009.06.12 영문공시관련추가 */

            // alert("dts_dscl.Text-->"+dts_dscl.Text);
            // alert("dts_dscl_Eng.Text-->"+dts_dscl_Eng.Text);

            scwin.setPar = function(arr) {

            };
            let wth = 730 + 5;
            let hgt = 785 + 30;
            let pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
            const options = {
                id: "ULDSTF92024",
                title: "공시안내문작성",
                type: "browserPopup",
                width: wth,
                height: hgt,
                callbackFn: "scwin.popupCallback"
            };

            $c.win.openPopup("/listingcommon/ULDSTF92024.gfm", options);
            scwin.getPar = OldGet;
            scwin.setPar = OldSet;
        }
    } else {
        await $c.win.alert("상호변경사유가 [영문상호변경], [약명변경]일 경우에만 안내문작성이 가능합니다.\r\n\r\n" + "나머지사유는 주식발행내역 화면으로 이동하시어 주식발행자료를 등록(주식발행사유:상호변경) 후 상호변경 안내공시를 하시기 바랍니다 ");
    }
};

