/**
 * @method
 * @name setSymblObj
 * @description set Symbl Obj 처리
 * @returns {void}
 * @hidden N
 */
scwin.setSymblObj = function() {
    if (scwin.vSYMBL_INPUT_CD === '1') {
        panel_ISUR_SYMBL.show("");
        $c.cm.setColumnProp(grd_IsuNm, "BFCHG_ISU_ENG_SYMBL", "Show", true);
        $c.cm.setColumnProp(grd_IsuNm, "AFCHG_ISU_ENG_SYMBL", "Show", true);
        $c.cm.setColumnProp(grd_HisCoNm, "AFCHG_ISUR_SYMBL", "Show", true);
        $c.cm.setColumnProp(grd_HisIsuNm, "AFCHG_ISU_ENG_SYMBL", "Show", true);
    } else if (scwin.vSYMBL_INPUT_CD === '2' || scwin.vSYMBL_INPUT_CD === "6") {
        panel_ISUR_SYMBL.hide();
        $c.cm.setColumnProp(grd_IsuNm, "BFCHG_ISU_ENG_SYMBL", "Show", false);
        $c.cm.setColumnProp(grd_IsuNm, "AFCHG_ISU_ENG_SYMBL", "Show", false);
        $c.cm.setColumnProp(grd_HisCoNm, "AFCHG_ISUR_SYMBL", "Show", false);
        $c.cm.setColumnProp(grd_HisIsuNm, "AFCHG_ISU_ENG_SYMBL", "Show", false);
    }
};

