};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사]를 선택하세요.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (edt_MKTACT_ENFORCE_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }
    if (vCurDate >= edt_MKTACT_ENFORCE_DD.getValue()) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_MKTACT_ENFORCE_DD.focus();
        return false;
    }
    if (cmb_COM_CHG_RSN_CD.getValue() === "") {
        await $c.win.alert("[변경사유]를 선택하세요.");
        cmb_COM_CHG_RSN_CD.focus();
        return false;
    }
    if (txb_AFCHG_COM_NM.getValue() === "") {
        await $c.win.alert("[한글회사명]을 입력하세요.");
        txb_AFCHG_COM_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AFCHG_COM_NM, 60, "한글회사명")) return false;
    if (txb_AFCHG_COM_ABBRV.getValue() === "") {
        await $c.win.alert("[한글회사약명]을 입력하세요.");
        txb_AFCHG_COM_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AFCHG_COM_ABBRV, 30, "한글회사약명")) return false;
    if (txb_AFCHG_COM_ENG_NM.getValue() === "") {
        await $c.win.alert("[영문회사명]을 입력하세요.");
        txb_AFCHG_COM_ENG_NM.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AFCHG_COM_ENG_NM, 60, "영문회사명")) return false;
    if (txb_AFCHG_COM_ENG_ABBRV.getValue() === "") {
        await $c.win.alert("[영문회사약명]을 입력하세요.");
        txb_AFCHG_COM_ENG_ABBRV.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_AFCHG_COM_ENG_ABBRV, 30, "영문회사약명")) return false;
    if (scwin.vSYMBL_INPUT_CD === '1') {
        if (txb_AFCHG_ISUR_SYMBL.getValue() === "") {
            await $c.win.alert("[영문회사심볼]을 입력하세요.");
            txb_AFCHG_ISUR_SYMBL.focus();
            return false;
        }
        if (!$c.lc.fn_chkCorpSymblDoubleInput(txb_AFCHG_ISUR_SYMBL.getValue(), txb_ISUR_CD.getValue(), dts_Symbl)) {
            await $c.win.alert(MSG_SYMBL_DOUBLE_INPUT);
            return false;
        }
    }

    /* 2009-04-24 상호변경 중복입력체크 */
    ///*
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, txb_ISUR_CD.getValue(), edt_MKTACT_ENFORCE_DD.getValue(), scwin.vBzProcsNo, LIST_BZ_TP_CD_148)) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description save 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.TR_JOB = 'I';
    if (await scwin.checkForm()) {
        if (dts_IsuNm.getCellData(1, "AFCHG_ISU_KOR_NM") === "") {
            await $c.win.alert("[종목명자동생성] 버튼을 선택하면 '변경후 종목명정보'가 자동 설정됩니다.");
            return;
        }
        if (!$c.lc.fn_isProcess(scwin.TR_JOB)) return;
        scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
        if (scwin.vBzProcsNo.length !== 14) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            dts_CoNm.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
            dts_CoNm.setCellData(1, "ISUR_CD", txb_ISUR_CD.getValue());
            await scwin.trs(TRS_IDX_INSERT);
        }
    }
};

/**
 * @method
 * @name update
