/**
 * @method
 * @name getIsuNmDisclsCtnt
 * @description get Isu Nm Discls Ctnt 처리
 * @returns {void}
 * @hidden N
 */
scwin.getIsuNmDisclsCtnt = function() {
    let vCtnt = "";
    vCtnt += "\r\n";
    vCtnt += "1. 변경내역(변경전 → 변경후)";
    vCtnt += "\r\n";
    vCtnt += "    - 한글종목명";
    vCtnt += "\r\n";
    for (let i = 1; i <= dts_IsuNm.getRowCount(); i++) {
        vCtnt += "         o " + dts_IsuNm.getCellData(i, "BFCHG_ISU_KOR_NM") + " → " + dts_IsuNm.getCellData(i, "AFCHG_ISU_KOR_NM");
        vCtnt += "\r\n";
    }
    vCtnt += "    - 영문종목명";
    vCtnt += "\r\n";
    for (let i = 1; i <= dts_IsuNm.getRowCount(); i++) {
        vCtnt += "         o " + dts_IsuNm.getCellData(i, "BFCHG_ISU_ENG_NM") + " → " + dts_IsuNm.getCellData(i, "AFCHG_ISU_ENG_NM");
        vCtnt += "\r\n";
    }
    vCtnt += "2. 변경일자: " + scwin.dateForm(edt_MKTACT_ENFORCE_DD.getValue());
    vCtnt += "\r\n";
    vCtnt += "3. 변경사유: ★★★★★★★★★★★★";
    vCtnt += "\r\n";
    return vCtnt;
};

/**
 * @method
 * @name dateForm
 * @description date Form 처리
 * @param {String} pStr pStr
 * @returns {void}
 * @hidden N
 */
scwin.dateForm = function(pStr) {
    let str = "";
    if (pStr === "") {
        str = "★★★★년" + "★★월" + "★★일";
    } else {
        str = pStr.substring(0, 4) + "년" + pStr.substring(4, 6) + "월" + pStr.substring(6, 8) + "일";
    }
    return str;
};

/**
 * @method
 * @name changeIsuNmByBatch
 * @description change Isu Nm By Batch 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.changeIsuNmByBatch = async function() {
    if (!await scwin.checkForm()) return false;
    grd_IsuNmredraw = false;
    const gAfComNm = dts_CoNm.getCellData(1, "AFCHG_COM_NM");
    let repCoNm = gAfComNm.replace("(주)", "");
    repCoNm = repCoNm.replace("㈜", "");
    repCoNm = repCoNm.replace("주식회사", "");
    const gAfComEngNm = dts_CoNm.getCellData(1, "AFCHG_COM_ENG_NM");
    let repCoEngNm = gAfComEngNm.replace("CO., LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD.", "");
    repCoEngNm = repCoEngNm.replace("CO., LTD", "");
    repCoEngNm = repCoEngNm.replace("CO.,LTD", "");
    repCoEngNm = repCoEngNm.replace("Co., Ltd", "");
    dts_IsuNm.setBroadcast(false);
    for (let i = 1; i <= dts_IsuNm.getRowCount(); i++) {
        const gStkcertKndCd = dts_IsuNm.getCellData(i, "STKCERT_KIND_CD");
        await scwin.stkkndcdReadSync(gStkcertKndCd);
        let vPreStr = "";
        const vPreEngStr = "";
        let gCompressCD = "";
        if (gStkcertKndCd !== '000') {
            gCompressCD = dts_STK_KND_CD.getCellData(1, "COMPRESS_CD");
        }
        let vStkKndSNm = dts_STK_KND_CD.getCellData(1, "STK_KND_SNM");
        let vStkKndEngNm = dts_STK_KND_CD.getCellData(1, "STK_KND_ENG_NM");
        let vStkKndEngSNm = dts_STK_KND_CD.getCellData(1, "STK_KND_ENG_SNM");
        const gPrefStkTpCd = dts_IsuNm.getCellData(i, "PREFSTK_TP_CD");
        if (gPrefStkTpCd === '2') {
            vPreStr = "(신형)";
            vStkKndSNm = vStkKndSNm + "B";
            vStkKndEngNm = vStkKndEngNm.replace("P", "PB");
            vStkKndEngSNm = vStkKndEngSNm.replace("P", "PB");
        }
        dts_IsuNm.setCellData(i, "AFCHG_ISU_KOR_NM", repCoNm + dts_STK_KND_CD.getCellData(1, "STK_KND_NM") + vPreStr);
        dts_IsuNm.setCellData(i, "AFCHG_ISU_KOR_ABBRV", dts_CoNm.getCellData(1, "AFCHG_COM_ABBRV") + vStkKndSNm);
        dts_IsuNm.setCellData(i, "AFCHG_ISU_ENG_NM", repCoEngNm + vStkKndEngNm);
        dts_IsuNm.setCellData(i, "AFCHG_ISU_ENG_ABBRV", dts_CoNm.getCellData(1, "AFCHG_COM_ENG_ABBRV") + vStkKndEngSNm);
        dts_IsuNm.setCellData(i, "AFCHG_ISU_ENG_SYMBL", dts_CoNm.getCellData(1, "AFCHG_ISUR_SYMBL") + gCompressCD);
    }
    dts_IsuNm.setBroadcast(true, true);
    grd_IsuNm.redraw = true;
    return true;
};
